import { test, expect } from '@playwright/test';
import { prisma } from '../lib/prisma';
import bcrypt from 'bcryptjs';
import { signInWithCredentials } from './helpers/auth';

// Temporary: captures the round-trip e-ticket at three viewports for the #137
// UI review. Not part of the suite's behavioural coverage.
test.describe('e-ticket visual', () => {
    const email = `eticket-${Date.now()}@example.com`;
    const password = 'Password123!';

    test.afterAll(async () => {
        const user = await prisma.user.findUnique({ where: { email } });
        if (!user) return;
        await prisma.booking.deleteMany({ where: { userId: user.id } });
        await prisma.user.delete({ where: { id: user.id } });
    });

    for (const viewport of [
        { name: 'phone', width: 390, height: 844 },
        { name: 'tablet', width: 768, height: 1024 },
        { name: 'desktop', width: 1440, height: 900 },
    ]) {
        test(`round-trip e-ticket at ${viewport.name}`, async ({ page }) => {
            await prisma.user.upsert({
                where: { email },
                update: {},
                create: {
                    name: 'E Ticket',
                    email,
                    password: await bcrypt.hash(password, 10),
                    emailVerified: new Date(),
                },
            });
            await page.setViewportSize({ width: viewport.width, height: viewport.height });
            await signInWithCredentials(page, { email, password });

            const outbound = await prisma.flight.findFirstOrThrow({
                where: { departureDate: { gt: new Date() } },
                orderBy: { departureDate: 'asc' },
            });
            const inbound = await prisma.flight.findFirstOrThrow({
                where: { id: { not: outbound.id }, departureDate: { gt: new Date() } },
                orderBy: { departureDate: 'asc' },
            });

            await page.goto(`/checkout?outbound=${outbound.id}&inbound=${inbound.id}`);
            await page.fill('input[placeholder="John"]', 'Rita');
            await page.fill('input[placeholder="Doe"]', 'Levi');
            await page.fill('input[type="date"]', '1985-03-20');
            await page.fill('input[placeholder="A00000000"]', 'US7778888');
            await page.click('button:has-text("Select Seats →")');

            await page.locator('button[title^="Select Seat"]').first().click();
            await page.getByRole('tab').nth(1).click();
            await page.locator('button[title^="Select Seat"]').first().click();

            await page.click('button:has-text("Review Booking →")');
            await page.locator('button:has-text("Confirm $")').click();
            await expect(page.locator('h2:has-text("Booking Confirmed!")')).toBeVisible({ timeout: 20000 });

            // The page must not scroll sideways at any width.
            const overflow = await page.evaluate(() =>
                document.documentElement.scrollWidth - document.documentElement.clientWidth
            );
            expect(overflow).toBeLessThanOrEqual(0);

            await page.screenshot({
                path: `/tmp/claude-1000/-home-scottdensmore-Developer-scottdensmore-travel-app/17bd93d2-3e04-4d30-81f1-e2014a294827/scratchpad/eticket-${viewport.name}.png`,
                fullPage: true,
            });
        });
    }
});

