import { loadEnvConfig } from '@next/env';
import type { FullConfig } from '@playwright/test';
import { prisma } from '../lib/prisma';

/**
 * The dev server compiles a route the first time something asks for it, and the
 * NextAuth credentials callback is expensive enough to cost more than an
 * assertion's default budget. Left alone that bill lands on whichever test signs
 * in first, so the suite fails by run order rather than by anything a test did:
 * running a passing spec on its own would fail it, and it would pass again
 * inside the suite where something else had already paid (#121).
 *
 * Paying it here puts the cost outside every test's budget.
 */
async function warmAuthRoutes(baseURL: string): Promise<void> {
    const deadline = Date.now() + 60_000;

    // The web server may still be starting; wait for it rather than warming
    // nothing. A failure here is not worth failing the run over -- the suite
    // still works, it is just paying the compile somewhere less convenient.
    while (Date.now() < deadline) {
        try {
            await fetch(`${baseURL}/login`);
            // Compiles the NextAuth route handler, which is one module: the
            // credentials provider and everything authorize() imports come with
            // it, so the first real sign-in finds it built.
            await fetch(`${baseURL}/api/auth/csrf`);
            await fetch(`${baseURL}/api/auth/callback/credentials`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: 'email=warmup@example.com&password=warmup',
                redirect: 'manual',
            });
            return;
        } catch {
            await new Promise(resolve => setTimeout(resolve, 500));
        }
    }

    console.warn('[global-setup] auth routes were not reachable; skipped warm-up.');
}

async function globalSetup(config: FullConfig): Promise<void> {
    loadEnvConfig(process.cwd());

    const baseURL = config.projects[0]?.use?.baseURL ?? 'http://localhost:3000';
    await warmAuthRoutes(baseURL);

    // After the warm-up, not before: the rejected sign-in above is exactly the
    // kind of attempt the limiter counts, and no test should start against a
    // budget this file spent.
    await prisma.authRateLimit.deleteMany();
    await prisma.$disconnect();
}

export default globalSetup;

